#!/usr/bin/env python3
"""Generates extraction_report.md from measured outputs (extraction_stats.json, old_data_audit*.json, ocr/*.jsonl, pages/*.jsonl)."""
import json, csv, collections, statistics as st
from pathlib import Path
OUT=Path("/mnt/user-data/outputs/data/rebuilt_v4"); S=json.load(open(OUT/"extraction_stats.json")); CFG=json.load(open(OUT/"scripts/doc_config.json"))
OA=json.load(open(OUT/"old_data_audit.json")); OX=json.load(open(OUT/"old_data_audit_extra.json"))
ISS=list(csv.DictReader(open(OUT/"extraction_issues.csv")))
D=list(S)
# placeholder counts per doc/part
PH={}
for d in D:
    for l in open(OUT/"pages"/f"{d}.jsonl",encoding="utf-8"):
        p=json.loads(l); part=next(x["part"] for x in CFG[d]["parts"] if x["pdf_start"]<=p["pdf_page"]<=x["pdf_end"])
        PH[(d,part)]=PH.get((d,part),0)+p["text_layout"].count("[●]")
o=[]; w=o.append
w("# Extraction report — Phase 2 (6 source PDFs)\n")
w("Generated by `scripts/08_write_report.py` from measured outputs. Nothing here was labeled, split or trained. Original PDFs and the old data files were not modified.\n")
w("## 1. Verified source corpus\n")
w("| doc_id | file | company (cover page) | document type | pdf pages | SHA-256 (first 12) |\n|---|---|---|---|---:|---|")
for d in D:
    v=S[d]; t=" + ".join(f"{p['document_type']} (pdf {p['pdf_start']}–{p['pdf_end']}, dated {p['doc_date']})" for p in v["parts"])
    w(f"| {d} | {v['source_filename']} | {v['company_name']} | {t} | {v['pdf_pages']} | `{v['sha256'][:12]}` |")
w(f"\nTotal: **{sum(S[d]['pdf_pages'] for d in D)} PDF pages**, 6 distinct files. A 7th document was not available and none was assumed. Project-Om and Shakti Polytarp ({OA['excluded_docs']['Project-Om_-RHP_with_RFS']} + {OA['excluded_docs']['shakti-polytarp-ltd-rhp']} old sections) are excluded because no PDFs exist.\n")
w("**Correction to my earlier message:** Century's issuer is Century Business Media Limited; the cover lists individuals as the promoters (my first reading of the unformatted text misattributed this).\n")
w("### AXIOM scope (provisionally in scope)\nThe PDF contains **both**: pdf pages 1–13 are an *abridged prospectus* (salient-features memorandum, ends with 'Declaration by the Company'); pdf pages 14–382 are the *full Red Herring Prospectus* dated 4 Sep 2026 (cover on pdf 14–16, TOC on pdf 17, body from pdf 18, declaration on pdf 382). They are kept as separate `document_part` values so they stay distinguishable. The abridged part repeats RHP content in condensed form, so it must not be split into a different evaluation split than the RHP part of the same company (they are the same document).\n")
w("## 2. Document types and why they matter for classification\n")
w("| doc_id | part | `[●]` blank-placeholder count (measured) |\n|---|---|---:|")
for (d,part),n in PH.items(): w(f"| {d} | {part} | {n} |")
w("""
Measured/verified differences (from cover pages and placeholder counts):
- **DRHP (Photonics, Maxwell, Ideas):** pre-filing drafts; price, dates and some figures are blank (`[●]`). Issue-detail sections therefore contain placeholders and no price band; cover pages mention a draft abridged prospectus.
- **RHP (Century, AXIOM-RHP):** book-built, may still contain blanks (see counts above); AXIOM's RHP says it 'will be updated upon filing with the RoC'.
- **Final Prospectus, fixed price (Quanto):** cover says *100% Fixed Price Issue* while all others say *100% Book Built*. Price-band / book-building concepts do not apply the same way; do not assume `ipo_details` sections mean the same thing across types.
- **Abridged prospectus (AXIOM pages 1–13):** summary-style; its headings (e.g. 'Details of the issue', 'Declaration by the Company') are not the ICDR chapter headings, so the chapter-title→category shortcut does not apply there.
- All six follow the SEBI ICDR template (Section I–X/XIII), so chapter titles are largely comparable. Listing platforms differ at least between Century (BSE SME, per its risk-factor text) and AXIOM (NSE Emerge, per its cover); the effect on wording was not measured.
""")
w("## 3. Sections extracted per PDF\n")
w("Two levels, **no labels yet**. L1 = chapter/part anchored on the document's own table of contents. L2 = sub-sections inside an L1 (bold left-margin headings); L2 records partition their L1 exactly. L1 includes one synthetic cover/front-matter and one contents-page record per RHP/DRHP (`front_matter`, `contents_page` flags; not for training).\n")
w("| doc_id | pdf pages | L1 total | L1 body chapters | L2 sub-sections | L2 median chars | L2 p95 chars | L2 max chars |\n|---|---:|---:|---:|---:|---:|---:|---:|")
for d in D:
    v=S[d]; w(f"| {d} | {v['pdf_pages']} | {v['L1_total']} | {v['L1_body_chapters_excluding_cover_and_toc']} | {v['L2_total']} | {v['L2_median_chars']} | {v['L2_p95_chars']} | {v['L2_max_chars']} |")
w(f"| **total** | {sum(S[d]['pdf_pages'] for d in D)} | {sum(S[d]['L1_total'] for d in D)} | {sum(S[d]['L1_body_chapters_excluding_cover_and_toc'] for d in D)} | {sum(S[d]['L2_total'] for d in D)} | | | |\n")
w("## 4. Checks that were actually run (script `07_validate_extraction.py`)\n")
w("""All 21 checks passed on the final outputs: JSONL parses; required fields present; unique IDs; no empty sections; exactly the 6 configured documents; no excluded documents; one company/source file per document; page ranges valid; every L2 has an L1 parent in the same document whose page range contains it; document_type matches the configured part; AXIOM abridged/RHP page confinement; no labels assigned; **L2 raw text equals L1 raw text exactly**; **independent non-whitespace character conservation** (sum of L1 sections = sum of page text, and L2 + contents page = page text, per document); every PDF page is in some L1; no TOC listing leaked into body chapters; every TOC entry resolved to a body location.

Limits of these checks: conservation proves no text was dropped or duplicated; it does **not** prove boundaries are semantically right. Two boundary bugs (below) passed conservation and were found only by the TOC-leak / size checks.
""")
w("### TOC anchoring\n")
w("| doc_id | TOC entries | resolved | on TOC page | forward scan | printed page only (heading text absent) | TOC vs body page disagreement |\n|---|---:|---:|---:|---:|---:|---|")
for d in D:
    t=S[d]["toc"]; a=t["anchoring"]; dis="; ".join(f"{x['heading'][:22]} TOC {x['toc_printed']} vs body {x['body_printed']}" for x in t["toc_vs_body_page_discrepancies"]) or "none"
    w(f"| {d} | {t['toc_entries_parsed_total']} | {t['toc_entries_parsed_total']-t['toc_entries_unresolved']} | {a.get('anchored_on_TOC_page',0)} | {a.get('anchored_by_forward_scan',0)} | {a.get('anchored_by_printed_page_only',0)} | {dis} |")
w("\n'Printed page only' (Century ×2): the TOC title has no matching body heading (e.g. TOC 'Restated Financial Information' vs body page opening with the auditor's report; TOC 'Other Regulatory and Statutory Disclosures' vs body heading 'Other Regulatory and Statutory Approvals'). Anchored at the TOC's printed page and flagged.\n")
w("## 5. Extraction problems — confirmed\n")
q=S["quanto_agroworld"]
ag=[json.loads(l) for l in open(OUT/"ocr/quanto_agroworld.jsonl")]
emb=[r for r in ag if r["kind"]=="image_with_text_layer"]
w(f"""1. **Quanto: scanned restated financial statements (F-1 to F-36, pdf 236–271).** pdf 236–241 are image-only (text layer holds only the page label); pdf 242–271 ({len(emb)} pages) are full-page images with an embedded OCR text layer showing OCR-typical errors (e.g. 'LIMITHD', 'Pormerly', '3O6927'). Fresh Tesseract OCR agrees with the embedded layer on a mean {round(st.mean(r['embedded_token_agreement_with_ocr'] for r in emb),3)} of tokens (min {min(r['embedded_token_agreement_with_ocr'] for r in emb)}, max {max(r['embedded_token_agreement_with_ocr'] for r in emb)}), and OCR mean word confidence is {round(st.mean(r['ocr_mean_word_conf'] for r in emb),1)}. **Financial figures in this block cannot be trusted from either source without checking the page images.** The block is its own L1 (`quanto_agroworld-L1-027`, 165,018 chars) flagged `scanned_insert_F1_to_F36`.
2. **Image-only photo pages with unusable OCR:** Maxwell pdf 173 (conf 32.7), Quanto pdf 162, 163 (conf 35.3 / 30.9). OCR output is noise; ignore it.
3. **Image-only pages with usable text:** Maxwell pdf 2, 4 ('This page is intentionally left blank'), Photonics pdf 223 (divider/index page, 94% agreement with its text layer), Photonics pdf 157 (flowchart image), Quanto pdf 299. OCR text is stored separately in `ocr/` and is **not** merged into section text.
4. **Ideas pdf 121–123:** private-use glyph U+F0D8 (Wingdings arrow bullet) in extracted text. Raw kept; normalisation choice deferred to Phase 4.
5. **Source inconsistency:** Quanto TOC lists 'Capital Structure' on p.63, body heading is on printed p.64 (p.63 is a 'left blank' page).
6. **Quanto manual structure override (documented in `doc_config.json`):** TOC lacks the restated-financials insert, so `Capitalization Statement` (TOC p.231 → pdf 235 is only a divider/index page) was split into: divider page (pdf 235), the scanned insert (pdf 236–271), and the capitalization table (pdf 272). Headings come from the document's own index text; no text was invented.
7. **Page numbers:** printed page numbers recovered on {min(S[d]['printed_page_numbers_recovered'] for d in D)}–{max(S[d]['printed_page_numbers_recovered'] for d in D)} of ~300–390 pages per document; each document has an offset jump where the restated financial statements are inserted (e.g. pdf−printed ≈ 4 → 51 in Photonics). `start_page`/`end_page` are always the physical PDF page; printed page is a secondary field and may be null.
8. **No ligature, CID, mojibake, U+FFFD or control-character problems** were found in any document's text layer (measured counts are in `extraction_stats.json`).
""")
w("## 6. Suspected / unresolved (not fixed)\n")
tot_max=sum(S[d]["risk_factor_numbering"]["max_number"] for d in D); tot_det=sum(S[d]["risk_factor_numbering"]["numbered_risk_headings_detected"] for d in D)
w("**Risk-factor segmentation is incomplete.** Numbered risk-factor headings detected vs highest number seen:\n")
w("| doc_id | numbered headings detected | max number | numbers missing | e.g. missing |\n|---|---:|---:|---:|---|")
for d in D:
    r=S[d]["risk_factor_numbering"]; w(f"| {d} | {r['numbered_risk_headings_detected']} | {r['max_number']} | {r['numbers_missing_from_1_to_max']} | {r['sample_missing']} |")
w(f"\nTotal {tot_det} detected of {tot_max} (max-number basis), i.e. {tot_max-tot_det} ({round(100*(tot_max-tot_det)/tot_max,1)}%) not isolated. In Ideas/AXIOM/Quanto the first nine are missing; in Ideas the early risk factors sit under mis-detected headings ('Customer Industry', 'Consequently, our results…'), so they are probably **merged into neighbouring sections** (suspected, not confirmed).\n")
w("**Other suspected issues (counts of flagged L2 records; flags are objective heuristics, not verdicts):**\n")
w("| doc_id | tiny (<150 chars) | heading-only | table-heavy (≥40% tabular lines) | very long (>20k, not split) |\n|---|---:|---:|---:|---:|")
for d in D:
    f=S[d]["L2_flag_counts"]; w(f"| {d} | {f.get('tiny_section',0)} | {f.get('heading_only',0)} | {f.get('table_heavy_check_structure',0)} | {f.get('very_long_section_not_split',0)} |")
w("""
- *Tiny / heading-only* sections are usually real sub-headings with little body (e.g. 'Criminal Litigation' → 'Nil'). They are kept, not deleted; whether to merge forward into a parent is a Phase 4 decision.
- *Very long* sections are mostly the definitions glossary, Articles of Association (up to 159,518 chars in AXIOM), approval tables and the Quanto scanned insert. Per rule 7 they are not split; they should be linked to parents if chunked later. Whether any contain merged unrelated topics is unchecked.
- *Table-heavy* sections come from `pdftotext -layout`, which keeps column alignment as spaces. Tables are **not** parsed into rows/columns; no table-structure verification has been done.
- Bold-line heading detection can still produce false headings (mid-sentence fragments) and miss unbolded ones; no precision/recall measurement against human-marked headings has been done.
- Header/footer removal in `section_text` covers only repeated margin lines found by position; Century/Ideas had 1 pattern, others 0. Running company-name headers inside the financial statements are not removed (raw and normalised text both keep them).
""")
w("## 7. Defects found in my own build and fixed (for transparency)\n")
w("""1. TOC parser merged Roman-numeral part headers ('I. GENERAL') into the next entry's title → 27 unresolved anchors in Century/Ideas and chapters swallowing 50+ pages. Fixed; 0 unresolved now.
2. First body chapter anchored on the TOC's own listing line (Century, Photonics, Ideas) → TOC text leaked into 'Definitions'. Found because contents-page sizes were implausible (46 chars). Fixed; leak check added.
3. Quanto 'SECTION I – GENERAL DEFINITIONS AND ABBREVIATIONS' was treated as a divider → Definitions chapter lost. Fixed with a rule (part followed by entry on a later page owns content).
4. Early L2 over-segmentation (1,000–1,700 per document) from bold table headers/fragments/signature lines → tightened rules; L2 now 777–1,104 per document.
5. A background OCR job was killed by a tool timeout and its partial results lost; re-run in resumable chunks. All 44 flagged pages were OCR'd.
""")
w("## 8. Audit of the old data files that were provided\n")
w("Inspected: `sections.json`, `structured_ipo_data.json`, `task_categories.json`. **Not provided and therefore not audited:** `train.py`, `evaluate_model.py`, any extraction/cleaning/build scripts, train/val/eval JSONL, the V3 chat-template audit. **No tokenizer or chat-template check was run.** Statements about how the old pipeline works are inferences from its outputs.\n")
oth=OX["other_label"]; sz=OX["old_section_size"]; art=OX["artifact_strings"]
_k="text_found_verbatim_in_pdf_text(alnum-normalised, first 70 chars)"
_p=[100*r["page_start_matches_a_pdf_page_where_text_occurs"]/r[_k] for r in OA["per_doc"].values()]
PMIN,PMAX=round(min(_p)),round(max(_p))
_d=[100*v["texts_repeated"]/v["items"] for v in OX["structured_ipo_data"].values()]
DMIN,DMAX=round(min(_d)),round(max(_d))
nsec=sum(r["old_section_count"] for r in OA["per_doc"].values())
w(f"""| finding (6 available docs, {nsec} old sections) | measured |
|---|---|
| Old sections per document | {', '.join(f"{d}: {r['old_section_count']}" for d,r in OA['per_doc'].items())} |
| Sections > 20k / > 50k characters | {sz['gt_20k_chars']} / {sz['gt_50k_chars']} (max {max(r['text_len_max'] for r in OA['per_doc'].values()):,}) |
| Century risk factors (pdf 23–46, ≈ 66+ individual risk factors) | stored as {len(OX['century_risk_factor_chapter_old_sections'])-1} sections incl. one 'INTERNAL RISK FACTORS' record of {max(x['chars'] for x in OX['century_risk_factor_chapter_old_sections']):,} chars |
| `other` label | {oth['n_other_in_6_docs']} of {oth['n_sections_6_docs']} sections; {oth['heading_le3_words_or_split_letter_pattern']} ({round(100*oth['heading_le3_words_or_split_letter_pattern']/oth['n_other_in_6_docs'])}%) have ≤3-word or split-letter headings; examples: {', '.join(repr(h) for h in oth['sample_headings'][:6])} |
| Broken-word artifacts ('PRIV ATE', 'V ALID', 'QUANT AGRJ', 'TATA AIG') | present in old sections ({', '.join(f"{k}: {v['occurrences_in_old_sections_json']}" for k,v in art.items())}); **0 occurrences in the PDFs' text layer** → introduced by the old extraction path (mechanism unconfirmed) |
| Label consistency | 414 headings repeat; **0 repeated headings carry conflicting labels** — consistent with heading-keyword rules rather than content-based labeling (inference) |
| Suspect label examples (suspected, not confirmed; taxonomy guide does not exist yet) | 'DIVIDEND POLICY' → legal_and_regulatory (8×); 'GENERAL RISKS' and 'RISK IN RELATION TO THE FIRST ISSUE' (cover boilerplate) → risk_factors (30×) |
| Label distribution (all 8 docs) | ipo_details 449, other 433, legal_and_regulatory 353 … declarations 4, qualitative_factors 7, related_party_transactions 14 |
| Taxonomy mismatch | `task_categories.json` has 11 keys; the 17-category taxonomy adds declarations, disclosures_and_definitions, financial_statements, other, qualitative_factors, related_party_transactions |
| Traceability | `page_start` equals a PDF page where the text occurs for {PMIN}–{PMAX}% of matched sections (per document); {sum(r['text_not_found_in_pdf'] for r in OA['per_doc'].values())} of {nsec} old sections ({round(100*sum(r['text_not_found_in_pdf'] for r in OA['per_doc'].values())/nsec)}%) do not match PDF text verbatim; for those, word overlap with the claimed page is ≥0.9 in {OX['old_text_not_found_verbatim_bag_of_words_overlap_with_claimed_page'].get('token_overlap>=0.9',0)} of {sum(OX['old_text_not_found_verbatim_bag_of_words_overlap_with_claimed_page'].values())} → same words in different order (consistent with table/column reflow), **not** evidence of fabricated text (bag-of-words test only) |
| `structured_ipo_data.json` | per-item `{{page, source_file, text}}`, no heading or section ID; 2,966–3,826 items per document, median ≈210 chars; {DMIN}–{DMAX}% of items share identical text with another item (duplicates or multi-category); 11 categories only |
| Old schema | `heading, category, page_start (int), text` — no end page, document ID, review status, or raw/normalised split |
""")
w("**Worth retaining:** the 17 category names; the idea of chapter-level anchors. **Rebuild:** extraction, segmentation, labeling, schema, splits.\n")
w("## 9. What was not done\n- No categories assigned, no annotation guide, no splits, no model-ready JSONL, no tokenizer audit, no near-duplicate check across documents, no manual comparison of table pages against rendered images beyond the scanned-page OCR, no audit of the old scripts (not provided).\n")
w("## 10. Files (all under `data/rebuilt_v4/`)\n")
w("""| file | purpose |
|---|---|
| `extracted_sections.jsonl` | master extraction: L1+L2 records, raw+normalised text, page provenance, flags; `category=null`, `review_status=unlabeled` |
| `pages/<doc>.jsonl` | page-level layout text + font-aware lines (source for everything) |
| `ocr/<doc>.jsonl` | OCR of flagged pages, stored separately with confidence and agreement score |
| `source_manifest.json`, `scan_inventory.json`, `structure_meta.json`, `structure_issues.json` | provenance and diagnostics |
| `extraction_stats.json`, `extraction_issues.csv`, `extraction_report.md` | this report's data (55 issue rows) |
| `old_data_audit.json`, `old_data_audit_extra.json` | old-file audit |
| `scripts/01…08_*.py`, `scripts/doc_config.json` | regenerate: 01 → 02 → 03 → 04 (OCR, slow, resumable) → 06 → 07 → 08; 05/05b independent |
""")
(OUT/"extraction_report.md").write_text("\n".join(o),encoding="utf-8")
print("written",len("\n".join(o)),"chars")
